    }
  ],
  "alternatives": [
    {
      "name": "listOption1",
      "list": [
        {
          "index": "1",
          "content": "<article xml:id=\"_art_2\" leos:editable=\"true\" leos:deletable=\"false\" leos:alternative=\"true\" leos:optionlist=\"listOption1\" leos:selectedoption=\"1\"><num xml:id=\"art_2__num\" leos:editable=\"false\">Article 2</num><heading xml:id=\"art_2__heading\">Article heading</heading><paragraph xml:id=\"art_n1__para_1\"><num xml:id=\"art_n1_s1B8uy\">1.</num><subparagraph xml:id=\"art_n1__para_1__subpara_1\"><content xml:id=\"art_n1_Qhm10R\"><p xml:id=\"art_n1_4CzCN4\"> Member States shall bring into force the laws, regulations and administrative provisions necessary to comply with this Directive by [...]  at the latest. They shall forthwith communicate to the Commission the text of those provisions. </p></content></subparagraph><subparagraph xml:id=\"art_n1__para_1__subpara_2\"><content xml:id=\"art_n1_bR03pA\"><p xml:id=\"art_n1_HTuqhq\">When Member States adopt those provisions, they shall contain a reference to this Directive or be accompanied by such a reference on the occasion of their official publication. Member States shall determine how such reference is to be made.</p></content></subparagraph></paragraph><paragraph xml:id=\"art_n1__para_2\"><num xml:id=\"art_n1_SzLpQM\">2.</num><content xml:id=\"art_n1_ApnR4I\"><p xml:id=\"art_n1_LBE4Df\">Member States shall communicate to the Commission the text of the main provisions of national law which they adopt in the field covered by this Directive.</p></content></paragraph></article>"
        },
        {
          "index": "2",
          "content": "<article xml:id=\"_art_n2\" leos:editable=\"true\" leos:deletable=\"false\" leos:alternative=\"true\" leos:optionlist=\"listOption1\" leos:selectedoption=\"2\"><num xml:id=\"art_n2_tMMjfH\" leos:editable=\"false\" leos:deletable=\"false\" leos:alternative=\"true\" leos:optionlist=\"listOption2\" leos:selectedoption=\"2\">Article 2</num><heading xml:id=\"art_n2_xM2j7b\">Transposition</heading><paragraph xml:id=\"art_n2__para_1\"><num xml:id=\"art_n2_i28JyH\">1.</num><subparagraph xml:id=\"art_n2__para_1__subpara_1\"><content xml:id=\"art_n2_U4XrFV\"><p xml:id=\"art_n2_iBvBjx\">Member States shall adopt and publish, by [...] <!-- [The time limit for transposition will be as short as possible and, generally, will not exceed two years] -->at the latest, the laws, regulations and administrative provisions necessary to comply with this Directive. They shall forthwith communicate to the Commission the text of those provisions.</p></content></subparagraph><subparagraph xml:id=\"art_n2__para_1__subpara_2\"><content xml:id=\"art_n2_dvPwbu\"><p xml:id=\"art_n2_tAP1Yk\">They shall apply those provisions from [...].</p></content></subparagraph><subparagraph xml:id=\"art_n2__para_1__subpara_3\"><content xml:id=\"art_n2_7WZHhd\"><p xml:id=\"art_n2_WSB7fW\">When Member States adopt those provisions, they shall contain a reference to this Directive or be accompanied by such a reference on the occasion of their official publication. Member States shall determine how such reference is to be made.</p></content></subparagraph></paragraph><paragraph xml:id=\"art_n2__para_2\"><num xml:id=\"art_n2_qw6cvY\">2.</num><content xml:id=\"art_n2_bTghug\"><p xml:id=\"art_n2_msixSB\">Member States shall communicate to the Commission the text of the main provisions of national law which they adopt in the field covered by this Directive.</p></content></paragraph></article>"
        }
      ]
    },
    {
