      "list": [
        {
          "index": "1",
          "content": "<article xml:id=\"_art_n4\" leos:editable=\"true\" leos:deletable=\"false\" leos:alternative=\"true\" leos:optionlist=\"listOption2\" leos:selectedoption=\"1\"><num xml:id=\"art_n4_LcUtyg\" leos:editable=\"false\">Article 4</num><heading xml:id=\"art_n4_Q27Lyk\">Addressees</heading><paragraph xml:id=\"art_n4__para_1\"><content xml:id=\"art_n4_QXd2sT\"><p xml:id=\"art_n4_9iYqIL\">This Directive is addressed to the Member States.</p></content></paragraph></article>"
        },
        {
