SET @str1 = '{
  "guidance": [
    {
      "targets": [
        {
          "destinationId": "_preface",
          "position": "AFTER"
        }
      ],
      "content": "<guidance id=\"guidance\" class=\"guidance-green-block\"><span id=\"preface-guidance\">[The standard guidance of an Explanatory Memorandum should be as follows. In principle it should not exceed 15 pages (in particularly complex cases a longer text may be justified). The language should be clear and simple, ensuring reader-friendliness for non-experts. All of the following elements are mandatory unless otherwise stated].</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_tblock_1__tblock_1",
          "position": "AFTER"
        }
      ],
      "content": "<guidance id=\"guidance-1-1\" class=\"guidance-green-block\"><span id=\"reasons-and-objective-guidance\">[Describe the reasons behind the proposal and the problem(s) it is expected to tackle. State if this is an initiative within the Regulatory Fitness Programme (REFIT). State any relevant institutional background of the proposal.]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_tblock_1__tblock_2",
          "position": "AFTER"
        }
      ],
      "content": "<guidance id=\"guidance-1-2\" class=\"guidance-green-block\"><span id=\"Consistency-with-existing-policy \">[Mention relevant existing policy provisions in the policy area and clarify how the proposal relates to them (e.g. differences, complementarity).]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_tblock_1__tblock_3",
          "position": "AFTER"
        }
      ],
      "content": "<guidance id=\"guidance-1-3\" class=\"guidance-green-block\"><span id=\"Consistency-with-other-Union-policies\">[Mention links with other key Union policies.]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_tblock_2__tblock_1",
          "position": "AFTER"
        }
      ],
      "content": "<guidance id=\"guidance-2-1\" class=\"guidance-green-block\"><span id=\"Legal-basis-guidance\">[Explain the choice of legal basis of the proposal. Where several feasible options seem to exist, justify the choice on the basis of objective criteria.]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_tblock_2__tblock_2",
          "position": "AFTER"
        }
      ],
      "content": "<guidance id=\"guidance-2-2\" class=\"guidance-green-block\"><span id=\"subsidiarity-guidance\">[Explain the Union dimension of the problem. Describe why the objectives cannot be adequately achieved by the Member States (necessity test). Explain why action at Union level would be more effective than action at national level and outline the added value of action at Union level (effectiveness test).]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_tblock_2__tblock_3",
          "position": "AFTER"
        }
      ],
      "content": "<guidance id=\"guidance-2-3\" class=\"guidance-green-block\"><span id=\"Proportionality-guidance\">[Explain the policy choices of the proposal and why they are considered proportionate (i.e. not going beyond what it necessary to achieve the objectives). Explain why it is considered the most suitable measure for achieving the objective. Where an Impact Assessment accompanies the proposal, reference should be made to the appropriate parts which discuss proportionality.]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_tblock_2__tblock_4",
          "position": "AFTER"
        }
      ],
      "content": "<guidance id=\"guidance-2-4\" class=\"guidance-green-block\"><span id=\"Choice-of-instrument-guidance\">[Where appropriate, explain the choice of the instrument.]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_tblock_3__tblock_1",
          "position": "AFTER"
        }
      ],
      "content": "<guidance id=\"guidance-3-1\" class=\"guidance-green-block\"><span id=\"Ex-post-evaluations-guidance\">[If applicable, summarise results of any ex-post evaluations/fitness checks of existing legislation. Clarify the link to the problems identified in the proposal.]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_tblock_3__tblock_2",
          "position": "AFTER"
        }
      ],
      "content": "<guidance id=\"guidance-3-2\" class=\"guidance-green-block\"><span id=\"Stakeholder-consultations-guidance\">[Describe the consultations carried out, summarise the input received, as well as how this was taken into account in the proposal. Where appropriate, explain where the Commission''s views diverge and why.]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_tblock_3__tblock_3",
          "position": "AFTER"
        }
      ],
      "content": "<guidance id=\"guidance-3-3\" class=\"guidance-green-block\"><span id=\"Collection-and-use-of-expertise-guidance\">[Where relevant, a short summary on the external expertise on which the Commission has relied (approach, range, advice received and used, publicly available information).]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_tblock_3__tblock_4",
          "position": "AFTER"
        }
      ],
      "content": "<guidance id=\"guidance-3-4\" class=\"guidance-green-block\"><span id=\"Impact-assessment-guidance\">[For proposals not supported by an Impact Assessment, please explain the reasons why no Impact Assessment was carried out with reference to the accompanying roadmap and the Guidelines on Better Regulation.]<br>[For proposals supported by an Impact Assessment, please provide links to the summary sheet and to the positive opinion of the Regulatory Scrutiny Board. In the absence of a positive opinion from the Board, please provide justification for proceeding with the initiative.]<br>[Explain which policy alternatives were examined, compare them and explain why the final proposal was considered to be the best policy choice.]<br>[Describe the main economic, social and environmental impacts of the preferred option, who would be affected and how. Include quantitative estimates of benefits and costs wherever possible and, if not available, explain why.]<br>[If the final policy proposal deviates from the options assessed in the impact assessment, clarify the differences in approach and their likely impact.]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_tblock_3__tblock_5",
          "position": "AFTER"
        }
      ],
      "content": "<guidance id=\"guidance-3-5\" class=\"guidance-green-block\"><span id=\"Regulatory-fitness-and-simplification-guidance\">[For proposals linked to REFIT and aimed at reducing regulatory burdens, provide, wherever possible, quantified estimates of the intended burden reduction.<br>            [Outline whether the proposal exempts micro-enterprises and the reasons why if it does not do so.]<br>[Explain how the proposal minimizes compliance costs for SMEs (via lighter regimes, mitigating measures, etc.) and other stakeholders, as well as any positive or negative impact on sectoral EU competitiveness or international trade.]<br>[Explain how the proposal is consistent with the \"Digital Check\" and is internet ready and appropriate for both the physical and digital environment (please see Better Regulation guideline and tool on ICT impacts in the Better Regulation Toolbox for more information).]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_tblock_3__tblock_6",
          "position": "AFTER"
        }
      ],
      "content": "<guidance id=\"guidance-3-6\" class=\"guidance-green-block\"><span id=\"Fundamental-rights-guidance\">[If the proposal has consequences for the protection of fundamental rights, explain how fundamental rights obligations have been met.]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_tblock_4",
          "position": "AFTER"
        }
      ],
      "content": "<guidance id=\"guidance-4-0\" class=\"guidance-green-block\"><span id=\"BUDGETARY-IMPLICATIONS-guidance\">[Outline the budgetary implications of the initiative (if any) and, where appropriate, refer to the \"financial statement\" showing the budgetary implications and the human and administrative resources required.]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_tblock_5__tblock_1",
          "position": "AFTER"
        }
      ],
      "content": "<guidance id=\"guidance-5-1\" class=\"guidance-green-block\"><span id=\"Implementation-plans-and-monitoring-guidance\">[Refer to the implementation planning associated with the measure, including the monitoring, evaluation and reporting framework set up to assist with its implementation and application and to report on its performance.]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_tblock_5__tblock_2",
          "position": "AFTER"
        }
      ],
      "content": "<guidance id=\"guidance-5-2\" class=\"guidance-green-block\"><span id=\"Explanatory-documents-guidance\">[Explain if the proposal requires Explanatory Documents on the transposition and why.]</span></guidance>"
    }
  ],
  "alternatives": [
  ],
  "structure": [
    {
      "name": "structure_03"
    }
  ]
}';
INSERT INTO CONFIG_CONTENT (VERSION_ID,CONTENT,CONTENT_STREAM_MIME_TYPE,CONTENT_STREAM_FILENAME,CONTENT_STREAM_ID,CONTENT_STREAM_LENGTH,AUDIT_C_BY,AUDIT_C_DATE,AUDIT_LAST_M_DATE,AUDIT_LAST_M_BY) VALUES ((SELECT id from CONFIG_VERSION WHERE CONFIG_ID IN (SELECT ID FROM CONFIG WHERE NAME ='EM-LP01-CONF')),@str1,'text/json','EM-LP01-CONF','0','0','admin',to_timestamp('22-01-21 08:25:53.270000000','DD-MM-RR HH24:MI:SSXFF'),to_timestamp('22-01-21 08:25:54.068000000','DD-MM-RR HH24:MI:SSXFF'),'admin');

SET @str1 = '{
  "guidance": [
    {
      "targets": [
        {
          "destinationId": "_141__p",
          "position": "AFTER-WRAPPER"
        }
      ],
      "content": "<guidance id=\"guidance-_141__p\" class=\"guidance-green-block\"><span id=\"_141__p-guidance\">[Please limit the general objective to max 1 - 2.<br> The general objective(s) shall explain how the Programme contributes to the achievement of the policy.<br>The general objectives should be specific, measurable, attainable, relevant and time-bound.<br>Please follow the Better Regulation Guidelines in drafting the objectives.]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_142__p",
          "position": "AFTER-WRAPPER"
        }
      ],
      "content": "<guidance id=\"guidance-_142__p\" class=\"guidance-green-block\"><span id=\"_142__p-guidance\">[Please limit the specific objective(s) to 2 - 3.<br>The specific objective(s) should be linked to the general one(s) and translate in concrete terms how the general objective(s) will be pursued.<br>The specific objectives should be specific, measurable, attainable, relevant and time-bound.<br>Please follow the Better Regulation Guidelines in drafting the objectives.]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_144__p",
          "position": "AFTER-WRAPPER"
        }
      ],
      "content": "<guidance id=\"guidance-_144__p\" class=\"guidance-green-block\"><span id=\"_144__p-guidance\">[A limited core set of indicators (i.e. one per objective) should be clearly defined and should generate information in a continuous and systematic way on implementation and performance.<br>The indicators should be relevant, accepted, credible, easy and robust.<br>Over the time indicators should be comparable and consistent for concepts, definitions and methods.<br> DGs should ensure the quality of indicators, the relevant aspects being:<br>(a) Effectiveness and timeliness: indicators should allow to monitor performance by providing information on progress on a regular basis and on achievements along the programming period.<br>(b) Efficiency: processes should be optimized for collection and processing of data, avoiding unnecessary or duplicative requests for information<br>(c) Relevance of the indicators and the need to limit the associated administrative burden.<br>(d) Clarity: indicators should be delivered in a clear and understandable form, with supporting metadata and in a form that facilitates proper interpretation and meaningful communication.<br>Each indicator should be accompanied by targets and baseline.]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_17__p",
          "position": "BEFORE-WRAPPER"
        }
      ],
      "content": "<guidance id=\"guidance-_17__p\" class=\"guidance-green-block\"><span id=\"_17__p-guidance\">[If more than one management mode is indicated, please provide details in the ‘Comments’ section]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_221__p",
          "position": "AFTER-WRAPPER"
        }
      ],
      "content": "<guidance id=\"guidance-_221__p\" class=\"guidance-green-block\"><span id=\"_221__p-guidance\">[DGs are to <i id=\"guidance-_221__p_i_1\">explain why</i> the management mode(s), funding implementation mechanism(s), payment modalities, and control strategy proposed are <i id=\"guidance-_221__p_i_2\">considered to be the most appropriate solutions</i> in this case – not only in terms of the policy/programme objectives but also in terms of balancing the internal control objectives (control effectiveness, efficiency and economy; i.e. low errors, fast contracting/paying and low control costs) – knowing that complexity of programmes can impact the error rates and (together with the volumes of transactions to be processed) also the costs of controls.<br><i id=\"guidance-_221__p_i_3\">Remark: Such justification is especially crucial when the programme is split into segments, with a deviating delivery set-up for some of them</i>.]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_222__p",
          "position": "AFTER-WRAPPER"
        }
      ],
      "content": "<guidance id=\"guidance-_222__p\" class=\"guidance-green-block\"><span id=\"_222__p-guidance\">[This includes explaining how the root causes of high error rates in the previous programme(s) are being addressed now, e.g. by simplifying previously complex modalities which were prone to error and/or by intensifying the (ex-ante and/or ex-post) controls for inherently high-risk activities.]</span></guidance>"
    },
    {
      "targets": [
        {
          "destinationId": "_223__p",
          "position": "AFTER-WRAPPER"
        }
      ],
      "content": "<guidance id=\"guidance-_223__p\" class=\"guidance-green-block\"><span id=\"_223__p-guidance\">[The costs of controls are to be estimated at Commission level and, for shared and indirect management, also (separately) at the level of Member States or Entrusted Entities. Also the source of the information (related to the cost of controls at the level of Member States or Entrusted Entities) and how they were estimated should be presented.<br>If for the whole or part of the programme the estimated total cost of controls (i.e. those of the Commission plus, if applicable, those of the Member States or the Entrusted Entities) are relatively high, then this should be explained by referring to possible cost drivers such as the specific risk-profile, the (dis)economies of scale in terms of number and size of the DG''s typical transactions processed, complexity of delivery mechanisms, etc.<br>Remark: Such justification is especially crucial when the programme is split into segments, with a deviating delivery set-up for some of them.<br>In terms of expected error rate(s), at the stage of the legislative proposals the aim is to maintain the error rate below the threshold of 2%. A different materiality threshold could only be discussed on a case-by-case basis in the light of the legislative debate, notably when the Legislative Authority would not (fully) endorse the proposed programme simplifications and/or would cap the controls, which would have consequences on the expected error rate. This would then require a coordinated approach.]</span></guidance>"
    }
  ],
  "structure": [
    {
      "name": "structure_07"
    }
  ]
}';
