                <TLCOrganization xml:id="_CONSIL" href="http://publications.europa.eu/resource/authority/corporate-body/CONSIL" showAs="Council of the European Union"/>
                <TLCOrganization xml:id="_EP" href="http://publications.europa.eu/resource/authority/corporate-body/EP" showAs="European Parliament"/>
                <TLCOrganization xml:id="_COM" href="http://publications.europa.eu/resource/authority/corporate-body/COM" showAs="European Commission"/>
                <TLCRole xml:id="_PRESID" href="http://publications.europa.eu/resource/authority/role/PRESID" showAs="President"/>
                <TLCReference xml:id="_DEC" name="docType" href="http://publications.europa.eu/resource/authority/resource-type/DEC"  showAs="Decision"/>
                <TLCReference xml:id="_legalBasis" name="contentSubject" href="http://eurovoc.europa.eu/5456" showAs="Legal basis"/>
                <TLCReference xml:id="_language" name="language" href="http://publications.europa.eu/resource/authority/language/ENG" showAs="en"/>
                <TLCReference xml:id="_procedure_YYYY_NNN" name="procedureReference" href="http://eur-lex.europa.eu/procedure/EN/YYYY_NNN" showAs="YYYY/NNNN (AAA)" shortForm="YYYY/NNN/AAA"/>
                <TLCReference xml:id="_azs3y" name="identifier" href="http://publications.europa.eu/resource/authority/document-identifier-format/COM_NUMBER" showAs="AAA(YYYY) NNN" shortForm="AAA/YYYY/NNN"/>
                <TLCConcept xml:id="_ART_DEF" href="http://publications.europa.eu/resource/subdivision-content/ART_DEF" showAs="Article on definitions"/>
            </references>
            <proprietary source="~_leos">
                <leos:templateVersion>3.1.0</leos:templateVersion>
                <leos:docVersion>0.1.0</leos:docVersion>
                <leos:template>SJ-019</leos:template>
                <leos:docTemplate>BL-019</leos:docTemplate>
            </proprietary>
        </meta>
        <preface xml:id="_preface">
            <container name="procedureIdentifier" xml:id="_preface__procedureIdentifier">
                <p xml:id="_preface__procedureIdentifier__p">
                    <docketNumber refersTo="~_procedure_YYYY_NNN" xml:id="_preface__procedureIdentifier__p__docketNumber"/>
                </p>
            </container>
            <longTitle xml:id="_preface__longtitle">
                <p xml:id="_preface__longtitle__p">
                    <docStage xml:id="_preface__longtitle__p__docstage">Proposal for a</docStage>
                    <docType refersTo="~_DEC" xml:id="_preface__longtitle__p__doctype">COUNCIL DECISION</docType>
                    <docPurpose xml:id="_preface__longtitle__p__docpurpose">on ...</docPurpose>
                </p>
            </longTitle>
        </preface>
        <preamble xml:id="_preamble">
            <formula xml:id="_preamble__formula_1" name="actingEntity">
                <p xml:id="_preamble__formula_1__p">THE COUNCIL OF THE EUROPEAN UNION,</p>
            </formula>
            <citations xml:id="_cits" leos:editable="false">
                <citation refersTo="~_legalBasis" xml:id="_cit_1" leos:editable="true">
                    <p xml:id="_cit_1__p">Having regard to the Treaty on the Functioning of the European Union, and in particular Article [...] thereof,</p>
                </citation>
                <citation xml:id="_cit_2" leos:editable="true">
                    <p xml:id="_cit_2__p">Having regard to the proposal from the European Commission,</p>
                </citation>
                <citation xml:id="_cit_3" leos:editable="true">
                    <p xml:id="_cit_3__p">After transmission of the draft legislative act to the national Parliaments,</p>
                </citation>
                <citation xml:id="_cit_4" leos:editable="true">
                    <p xml:id="_cit_4__p">Having regard to the opinion of the European Parliament<authorialNote xml:id="_authorialnote_1" marker="1" placement="bottom"><p xml:id="_authorialNote_1__p">OJ C [...], [...], p. [...]</p></authorialNote>,</p>
                </citation>
                <citation xml:id="_cit_5" leos:editable="true">
                    <p xml:id="_cit_5__p">Having regard to the opinion of the European Economic and Social Committee<authorialNote xml:id="_authorialnote_2" marker="2" placement="bottom"><p xml:id="_authorialNote_2__p">OJ C [...], [...], p. [...]</p></authorialNote>,</p>
