                <paragraph xml:id="_art_n1__para_1">
                    <num xml:id="_art_n1_s1B8uy">1.</num>
                    <subparagraph xml:id="_art_n1__para_1__subpara_1">
                        <content xml:id="_art_n1_Qhm10R">
                            <p xml:id="_art_n1_4CzCN4">Member States shall bring into force the laws, regulations and
                                administrative provisions necessary to comply with this Directive by [...] <!-- ** Field Guidance** [The time limit for transposition will be as short as possible and, generally, will not exceed two years] -->at the
                                latest. They shall forthwith communicate to the Commission the text of those provisions.
                            </p>
                        </content>
                    </subparagraph>
                    <subparagraph xml:id="_art_n1__para_1__subpara_2">
                        <content xml:id="_art_n1_bR03pA">
                            <p xml:id="_art_n1_HTuqhq">When Member States adopt those provisions, they shall contain a
                                reference to this Directive or be accompanied by such a reference on the occasion of
                                their official publication. Member States shall determine how such reference is to be
                                made.
                            </p>
                        </content>
                    </subparagraph>
                </paragraph>
                <paragraph xml:id="_art_n1__para_2">
                    <num xml:id="_art_n1_SzLpQM">2.</num>
                    <content xml:id="_art_n1_ApnR4I">
                        <p xml:id="_art_n1_LBE4Df">Member States shall communicate to the Commission the text of the main
                            provisions of national law which they adopt in the field covered by this Directive.
                        </p>
                    </content>
                </paragraph>
            </article>
            <!-- /Model A-->
            <!-- Model B -->
            <!-- <article xml:id="_art_n2" leos:editable="true" leos:alternative="true" leos:optionlist="listOption1">
                <num xml:id="_art_n2_tMMjfH" leos:editable="false">Article #</num>
                <heading xml:id="_art_n2_xM2j7b">Transposition</heading>
                <paragraph xml:id="_art_n2__para_1">
                    <num xml:id="_art_n2_i28JyH">1.</num>
                    <subparagraph xml:id="_art_n2__para_1__subpara_1">
                        <content xml:id="_art_n2_U4XrFV">
                            <p xml:id="_art_n2_iBvBjx">Member States shall adopt and publish, by [...]  ** Field Guidance** [The time limit for transposition will be as short as possible and, generally, will not exceed two years] -->
                            <!--   at the latest, the laws, regulations and administrative provisions necessary to comply with this Directive.
                                They shall forthwith communicate to the Commission the text of those provisions.
                            </p>
                        </content>
                    </subparagraph>
                    <subparagraph xml:id="_art_n2__para_1__subpara_2">
                        <content xml:id="_art_n2_dvPwbu">
                            <p xml:id="_art_n2_tAP1Yk">They shall apply those provisions from [...].</p>
                        </content>
                    </subparagraph>
                    <subparagraph xml:id="_art_n2__para_1__subpara_3">
                        <content xml:id="_art_n2_7WZHhd">
                            <p xml:id="_art_n2_WSB7fW">When Member States adopt those provisions, they shall contain a
                                reference to this Directive or be accompanied by such a reference on the occasion of
                                their official publication. Member States shall determine how such reference is to be
                                made.
                            </p>
                        </content>
                    </subparagraph>
                </paragraph>
                <paragraph xml:id="_art_n2__para_2">
                    <num xml:id="_art_n2_qw6cvY">2.</num>
                    <content xml:id="_art_n2_bTghug">
                        <p xml:id="_art_n2_msixSB">Member States shall communicate to the Commission the text of the main
                            provisions of national law which they adopt in the field covered by this Directive.
                        </p>
                    </content>
                </paragraph>
            </article>
			-->
            <!-- /Model B -->
			<!-- ** Model B guidance ** (to be used where it is essential that the national provisions be applied from the same date in all Member States) -->
            <article xml:id="_art_n3" leos:editable="true" leos:deletable="false" leos:autonumbering="true">
                <num xml:id="_art_n3_SY9NX8" leos:editable="false">Article 4</num>
                <heading xml:id="_art_n3_ZoKQ0d">Entry into force</heading>
                <paragraph xml:id="_art_n3__para_1">
	                <content xml:id="_art_n3_KEx5uM">
	                    <p xml:id="_art_n3_EX7xHn">This Directive shall enter into force on the [...] day following that of its publication in the<i xml:id="_art_n3_9vIgN0">Official Journal of the European Union</i>.</p>
	                </content>
                </paragraph>
            </article>

            <article xml:id="_art_n4" leos:editable="true" leos:deletable="false" leos:alternative="true" leos:optionlist="listOption2" leos:selectedoption="1" leos:autonumbering="true">
                <num xml:id="_art_n4_LcUtyg" leos:editable="false">Article 5</num>
                <heading xml:id="_art_n4_Q27Lyk">Addressees</heading>
                <paragraph xml:id="_art_n4__para_1">
					<content xml:id="_art_n4_QXd2sT">
	                    <p xml:id="_art_n4_9iYqIL">This Directive is addressed to the Member States.</p>
	                </content>
                </paragraph>
                <!-- <paragraph xml:id="_art_n4__para_1">
	                <content xml:id="_art_n5_kfM6hD">
	                    <p xml:id="_art_n5_yZp7Mq">This Directive is addressed to the Member States in accordance with the Treaties.</p>
	                </content>
                </paragraph> -->
            </article>

        </body>
        <conclusions xml:id="_conclusions">
            <p xml:id="_conclusions__p_1">Done at <location refersTo="~_BEL_BRU" xml:id="_conclusions__p__location_1">Brussels</location>, <date date="9999-01-01" xml:id="_akn_aviQud"/></p>
            <block name="signatory" xml:id="_conclusions__block_1">
                <signature xml:id="_conclusions__block_1__signature_1">
                    <organization refersTo="~_EP" xml:id="_conclusions__block_1__signature_1__organization">For the European Parliament</organization>
                    <role refersTo="~_PRESID" xml:id="_conclusions__block_1__signature_1__role">The President</role>
                    <person refersTo="" xml:id="_conclusions__block_1__signature_1__person">[...]</person>
                </signature>
                <signature xml:id="_conclusions__block_1__signature_2">
                    <organization refersTo="~_CONSIL" xml:id="_conclusions__block_1__signature_2__organization">For the Council</organization>
                    <role refersTo="~_PRESID" xml:id="_conclusions__block_1__signature_2__role">The President</role>
                    <person refersTo="" xml:id="_conclusions__block_1__signature_2__person">[...]</person>
                </signature>
            </block>
        </conclusions>
    </bill>
</akomaNtoso>';
