                    <p xml:id="_cit_5__p">Having regard to the opinion of the Committee of the Regions<authorialNote xml:id="_authorialnote_2" marker="2" placement="bottom"><p xml:id="_authorialNote_2__p">OJ C [...], [...], p. [...]</p></authorialNote>,</p>
