                    <b xml:id="_body__level_1__heading__b">FRAMEWORK OF THE PROPOSAL/INITIATIVE</b>
                </heading>
            </level>
            <level leos:depth="2" xml:id="_body__level_11" leos:editable="true" leos:deletable="false">
                <num xml:id="_body__level_11__num">1.1.</num>
                <heading xml:id="_body__level_11__heading" leos:editable="false">
                    <b xml:id="_body__level_11__heading__b" leos:editable="false">Title of the proposal/initiative</b>
                </heading>
                <content xml:id="_body__level_11__subparagraph__content">
                    <p xml:id="_body__level_11__subparagraph__content__p">[...]</p>
                </content>
            </level>
            <level leos:depth="2" xml:id="_body__level_12" leos:editable="true" leos:deletable="false">
                <num xml:id="_body__level_12__num">1.2.</num>
                <heading xml:id="_body__level_12__heading" leos:editable="false">
                    <b xml:id="_body__level_12__heading__b" leos:editable="false">Policy area(s) concerned</b>
                </heading>
                <content xml:id="_body__level_12__subparagraph__content">
                    <p xml:id="_body__level_12__subparagraph__content__p">[...]</p>
                </content>
            </level>
            <level leos:depth="2" xml:id="_body__level_13" leos:editable="false" leos:deletable="false">
                <num xml:id="_body__level_13__num">1.3.</num>
                <heading xml:id="_body__level_13__heading" leos:editable="false">
                    <b xml:id="_body__level_13__heading__b">The proposal/initiative relates to:</b>
                </heading>
                <list leos:editable="false" class="CHECK" xml:id="_body__level_13__list">
                    <indent xml:id="_body__level_13__list__indent_1">
                        <num xml:id="_body__level_13__list__indent_1__num">
                            <inline name="unchecked" xml:id="_body__level_13__list__indent_1__num__inline">
                                <b xml:id="_body__level_13__list__indent_1__num__inline__b">&#x2610;</b>
                            </inline>
                        </num>
                        <content xml:id="_body__level_13__list__indent_1__content">
                            <p xml:id="_body__level_13__list__indent_1__content__p">
                                <b xml:id="_body__level_13__list__indent_1__content__p__b">a new action</b>
                            </p>
                        </content>
                    </indent>
                    <indent xml:id="_body__level_13__list__indent_2_2">
                        <num xml:id="_body__level_13__list__indent_2_2__num">
                            <inline name="unchecked" xml:id="_body__level_13__list__indent_2_2__num__inline">
                                <b xml:id="_body__level_13__list__indent_2_2__num__inline__b">&#x2610;</b>
                            </inline>
                        </num>
                        <content xml:id="_body__level_13__list__indent_2_2__content">
                            <p xml:id="_body__level_13__list__indent_2_2__content__p">
                                <b xml:id="_body__level_13__list__indent_2_2__content__p__b">a new action following a pilot project/preparatory action
                                    <authorialNote marker="1" placement="bottom" xml:id="_body__level_13__list__indent_2_2__content__p__b__authorialnote">
                                        <p xml:id="_body__level_13__list__indent_2_2__content__p__b__authorialnote__p">As referred to in Article 58(2)(a) or (b) of the Financial Regulation.</p>
                                    </authorialNote>
                                </b>
                            </p>
                        </content>
                    </indent>
                    <indent xml:id="_body__level_13__list__indent_3_3">
                        <num xml:id="_body__level_13__list__indent_3_3__num">
                            <inline name="unchecked" xml:id="_body__level_13__list__indent_3_3__num__inline">
                                <b xml:id="_body__level_13__list__indent_3_3__num__inline__b">&#x2610;</b>
                            </inline>
                        </num>
                        <content xml:id="_body__level_13__list__indent_3_3__content">
                            <p xml:id="_body__level_13__list__indent_3_3__content__p">
                                <b xml:id="_body__level_13__list__indent_3_3__content__p__b">the extension of an existing action</b>
                            </p>
                        </content>
                    </indent>
                    <indent xml:id="_body__level_13__list__indent_4">
                        <num xml:id="_body__level_13__list__indent_4__num">
                            <inline name="unchecked" xml:id="_body__level_13__list__indent_4__num__inline">
                                <b xml:id="_body__level_13__list__indent_4__num__inline__b">&#x2610;</b>
                            </inline>
                        </num>
                        <content xml:id="_body__level_13__list__indent_4__content">
                            <p xml:id="_body__level_13__list__indent_4__content__p">
                                <b xml:id="_body__level_13__list__indent_4__content__p__b">a merger or redirection of one or more actions towards another/a new action</b>
                            </p>
                        </content>
                    </indent>
                </list>
            </level>
            <level leos:depth="2" xml:id="_body__level_14" leos:editable="false" leos:deletable="false">
                <num xml:id="_body__level_14__num">1.4.</num>
                <heading xml:id="_body__level_14__heading" leos:editable="false">
                    <b xml:id="_body__level_14__heading__b">Objective(s)</b>
                </heading>
            </level>
            <level leos:depth="3" xml:id="_body__level_141" leos:editable="true" leos:deletable="false">
                <num xml:id="_body__level_141__num">1.4.1.</num>
                <heading xml:id="_body__level_141__heading" leos:editable="false">
                    <i xml:id="_body__level_141__heading__i" leos:editable="false">General objective(s)</i>
                </heading>
                <content xml:id="_body__level_141__content">
                    <p xml:id="_141__p">[...]</p>
                </content>
            </level>
            <level leos:depth="3" xml:id="_body__level_142" leos:editable="true" leos:deletable="false">
                <num xml:id="_body__level_142__num">1.4.2.</num>
                <heading xml:id="_body__level_142__heading" leos:editable="false">
                    <i xml:id="_body__level_142__heading__i" leos:editable="false">Specific objective(s)</i>
                </heading>
                <subparagraph xml:id="_body__level_142__subparagraph_3">
                    <content xml:id="_body__level_142__subparagraph_3__content">
                        <p xml:id="_body__level_142__subparagraph_3__content__p">
                            <u xml:id="_body__level_142__subparagraph_3__content__p__u">Specific objective No</u>
                        </p>
                    </content>
                </subparagraph>
                <subparagraph xml:id="_body__level_142__subparagraph_4">
                    <content xml:id="_body__level_142__subparagraph_4__content">
                        <p xml:id="_142__p">[...]</p>
                    </content>
                </subparagraph>
            </level>
            <level leos:depth="3" xml:id="_body__level_143" leos:editable="true" leos:deletable="false">
                <num xml:id="_body__level_143__num">1.4.3.</num>
                <heading xml:id="_body__level_143__heading" leos:editable="false">
                    <i xml:id="_body__level_143__heading__i" leos:editable="false">Expected result(s) and impact</i>
                </heading>
                <subparagraph xml:id="_body__level_143__subparagraph_3" leos:editable="false">
                    <content xml:id="_body__level_143__subparagraph_3__content">
                        <p xml:id="_body__level_143__subparagraph_3__content__p" leos:editable="false">
                            <i leos:editable="false" xml:id="_body__level_143__subparagraph_3__content__p__i">Specify the effects which the proposal/initiative should have on the beneficiaries/groups targeted.</i>
                        </p>
                    </content>
                </subparagraph>
                <subparagraph xml:id="_body__level_143__subparagraph_4">
                    <content xml:id="_body__level_143__subparagraph_4__content">
                        <p xml:id="_body__level_143__subparagraph_4__content__p">[...]</p>
                    </content>
                </subparagraph>
            </level>
            <level leos:depth="3" xml:id="_body__level_144" leos:editable="true" leos:deletable="false">
                <num xml:id="_body__level_144__num">1.4.4.</num>
                <heading xml:id="_body__level_144__heading" leos:editable="false">
                    <i xml:id="_body__level_144__heading__i" leos:editable="false">Indicators of performance</i>
                </heading>
                <subparagraph xml:id="_body__level_144__subparagraph_3" leos:editable="false">
                    <content xml:id="_body__level_144__subparagraph_3__content">
                        <p xml:id="_body__level_144__subparagraph_3__content__p" leos:editable="false">
                            <i leos:editable="false" xml:id="_body__level_144__subparagraph_3__content__p__i">Specify the indicators for monitoring progress and achievements.</i>
                        </p>
                    </content>
                </subparagraph>
                <subparagraph xml:id="_body__level_144__subparagraph_4">
                    <content xml:id="_body__level_144__subparagraph_4__content">
                        <p xml:id="_144__p">[...]</p>
                    </content>
                </subparagraph>
            </level>
            <level leos:depth="2" xml:id="_body__level_15" leos:editable="false" leos:deletable="false">
                <num xml:id="_body__level_15__num">1.5.</num>
                <heading xml:id="_body__level_15__heading" leos:editable="false">
                    <b xml:id="_body__level_15__heading__b">Grounds for the proposal/initiative</b>
                </heading>
            </level>
            <level leos:depth="3" xml:id="_body__level_151" leos:editable="true" leos:deletable="false">
                <num xml:id="_body__level_151__num">1.5.1.</num>
                <heading xml:id="_body__level_151__heading" leos:editable="false">
                    <i xml:id="_body__level_151__heading__i" leos:editable="false">Requirement(s) to be met in the short or long term including a detailed timeline for roll-out of the implementation of the initiative</i>
                </heading>
                <content xml:id="_body__level_151__subparagraph__content">
                    <p xml:id="_body__level_151__subparagraph__content__p">[...]</p>
                </content>
            </level>
            <level leos:depth="3" xml:id="_body__level_152" leos:editable="true" leos:deletable="false">
                <num xml:id="_body__level_152__num">1.5.2.</num>
                <heading xml:id="_body__level_152__heading" leos:editable="false">
                    <i xml:id="_body__level_152__heading__i" leos:editable="false">Added value of Union involvement (it may result from different factors, e.g. coordination gains, legal certainty, greater effectiveness or complementarities). For the purposes of this point ''added value of Union involvement'' is the value resulting from Union intervention, which is additional to the value that would have been otherwise created by Member States alone.</i>
                </heading>
                <subparagraph xml:id="_body__level_152__subparagraph_3">
                    <content xml:id="_body__level_152__subparagraph_3__content">
                        <p xml:id="_body__level_152__subparagraph_3__content__p">Reasons for action at European level (ex-ante) […]</p>
                    </content>
                </subparagraph>
                <subparagraph xml:id="_body__level_152__subparagraph_4">
                    <content xml:id="_body__level_152__subparagraph_4__content">
                        <p xml:id="_body__level_152__subparagraph_4__content__p">Expected generated Union added value (ex-post) […]</p>
                    </content>
                </subparagraph>
            </level>
            <level leos:depth="3" xml:id="_body__level_153" leos:editable="true" leos:deletable="false">
                <num xml:id="_body__level_153__num">1.5.3.</num>
                <heading xml:id="_body__level_153__heading" leos:editable="false">
                    <i xml:id="_body__level_153__heading__i" leos:editable="false">Lessons learned from similar experiences in the past</i>
                </heading>
                <content xml:id="_body__level_153__subparagraph__content">
                    <p xml:id="_body__level_153__subparagraph__content__p">[...]</p>
                </content>
            </level>
            <level leos:depth="3" xml:id="_body__level_154" leos:editable="true" leos:deletable="false">
                <num xml:id="_body__level_154__num">1.5.4.</num>
                <heading xml:id="_body__level_154__heading" leos:editable="false">
                    <i xml:id="_body__level_154__heading__i" leos:editable="false">Compatibility with the Multiannual Financial Framework and possible synergies with other appropriate instruments</i>
                </heading>
                <content xml:id="_body__level_154__subparagraph__content">
                    <p xml:id="_body__level_154__subparagraph__content__p">[...]</p>
                </content>
            </level>
            <level leos:depth="3" xml:id="_body__level_155" leos:editable="true" leos:deletable="false">
                <num xml:id="_body__level_155__num">1.5.5.</num>
                <heading xml:id="_body__level_155__heading" leos:editable="false">
                    <i xml:id="_body__level_155__heading__i" leos:editable="false">Assessment of the different available financing options, including scope for redeployment</i>
                </heading>
                <content xml:id="_body__level_155__subparagraph__content">
                    <p xml:id="_body__level_155__subparagraph__content__p">[...]</p>
                </content>
            </level>
            <level leos:depth="2" xml:id="_body__level_16" leos:editable="false" leos:deletable="false">
                <num xml:id="_body__level_16__num">1.6.</num>
                <heading xml:id="_body__level_16__heading" leos:editable="false">
