                                </num>
                                <content xml:id="_body__level_16__list__indent_1__list__indent_1__content">
                                    <p xml:id="_body__level_16__list__indent_1__list__indent_1__content__p">in effect from
                                        <inline name="date" period="d.m.yy" xml:id="_body__level_16__list__indent_1__list__indent_1__content__p__inline_1">[DD.MM]YYYY</inline>
                                        to
                                        <inline name="date" period="d.m.yy" xml:id="_body__level_16__list__indent_1__list__indent_1__content__p__inline_2">[DD.MM]YYYY</inline>
                                    </p>
                                </content>
                            </indent>
                            <indent xml:id="_body__level_16__list__indent_1__list__indent_2">
                                <num xml:id="_body__level_16__list__indent_1__list__indent_2__num">
                                    <inline name="unchecked" xml:id="_body__level_16__list__indent_1__list__indent_2__num__inline">&#x2610;</inline>
                                </num>
                                <content xml:id="_body__level_16__list__indent_1__list__indent_2__content">
                                    <p xml:id="_body__level_16__list__indent_1__list__indent_2__content__p">Financial impact from
                                        <inline name="date" period="yy" xml:id="_body__level_16__list__indent_1__list__indent_2__content__p__inline_1">YYYY</inline>
                                        to
                                        <inline name="date" period="yy" xml:id="_body__level_16__list__indent_1__list__indent_2__content__p__inline_2_2">YYYY</inline>
