                                        <inline name="date" period="yy" xml:id="_body__level_16__list__indent_1__list__indent_2__content__p__inline_3_3">YYYY</inline>
                                        to
                                        <inline name="date" period="yy" xml:id="_body__level_16__list__indent_1__list__indent_2__content__p__inline_4">YYYY</inline>
                                        for payment appropriations.
                                    </p>
