                    <authorialNote leos:editable="false" marker="2" placement="bottom" xml:id="_body__level_17__heading__authorialnote">
                        <p xml:id="_body__level_17__heading__authorialnote__p">Details of budget implementation methods and references to the Financial Regulation may be found on the BUDGpedia site:
                            https://myintracomm.ec.europa.eu/corp/budget/financial-rules/budget-implementation/Pages/implementation-methods.aspx.
                        </p>
                    </authorialNote>
                </heading>
                <list class="CHECK" xml:id="_body__level_17__list" leos:editable="false">
                    <indent leos:editable="false" xml:id="_body__level_17__list__indent_1">
