                                    <b leos:editable="false" xml:id="_body__level_17__list__indent_1__subparagraph__content__p__b">Direct management</b>
                                    by the Commission</p>
                            </content>
                        </subparagraph>
                        <list leos:editable="false" class="CHECK" xml:id="_body__level_17__list__indent_1__list">
