                                <num xml:id="_body__level_17__list__indent_1__list__indent_1__num">
                                    <inline name="unchecked" xml:id="_body__level_17__list__indent_1__list__indent_1__num__inline">&#x2610;</inline>
                                </num>
                                <content xml:id="_body__level_17__list__indent_1__list__indent_1__content">
                                    <p xml:id="_body__level_17__list__indent_1__list__indent_1__content__p">by its departments, including by its staff in the Union delegations;</p>
                                </content>
                            </indent>
                            <indent leos:editable="false" xml:id="_body__level_17__list__indent_1__list__indent_2">
                                <num xml:id="_body__level_17__list__indent_1__list__indent_2__num">
                                    <inline name="unchecked" xml:id="_body__level_17__list__indent_1__list__indent_2__num__inline">&#x2610;</inline>
                                </num>
                                <content xml:id="_body__level_17__list__indent_1__list__indent_2__content">
                                    <p xml:id="_body__level_17__list__indent_1__list__indent_2__content__p">by the executive agencies</p>
                                </content>
                            </indent>
                        </list>
                    </indent>
                    <indent leos:editable="false" xml:id="_body__level_17__list__indent_2_2">
                        <num xml:id="_body__level_17__list__indent_2_2__num">
                            <inline name="unchecked" xml:id="_body__level_17__list__indent_2_2__num__inline">&#x2610;</inline>
                        </num>
                        <content xml:id="_body__level_17__list__indent_2_2__content">
                            <p xml:id="_body__level_17__list__indent_2_2__content__p">
                                <b leos:editable="false" xml:id="_body__level_17__list__indent_2_2__content__p__b">Shared management</b>
                                with the Member States</p>
                        </content>
                    </indent>
                    <indent leos:editable="false" xml:id="_body__level_17__list__indent_3">
                        <num xml:id="_body__level_17__list__indent_3__num">
                            <inline name="unchecked" xml:id="_body__level_17__list__indent_3__num__inline">&#x2610;</inline>
                        </num>
                        <subparagraph leos:editable="false" xml:id="_body__level_17__list__indent_3__subparagraph">
                            <content xml:id="_body__level_17__list__indent_3__subparagraph__content">
                                <p xml:id="_body__level_17__list__indent_3__subparagraph__content__p">
                                    <b leos:editable="false" xml:id="_body__level_17__list__indent_3__subparagraph__content__p__b">Indirect management</b>
                                    by entrusting budget implementation tasks to:</p>
                            </content>
                        </subparagraph>
                        <list leos:editable="false" class="CHECK" xml:id="_body__level_17__list__indent_3__list">
                            <indent leos:editable="false" xml:id="_body__level_17__list__indent_3__list__indent_1">
                                <num xml:id="_body__level_17__list__indent_3__list__indent_1__num">
                                    <inline name="unchecked" xml:id="_body__level_17__list__indent_3__list__indent_1__num__inline">&#x2610;</inline>
                                </num>
                                <content xml:id="_body__level_17__list__indent_3__list__indent_1__content">
                                    <p xml:id="_body__level_17__list__indent_3__list__indent_1__content__p">third countries or the bodies they have designated;</p>
                                </content>
                            </indent>
                            <indent leos:editable="false" xml:id="_body__level_17__list__indent_3__list__indent_2_2">
                                <num xml:id="_body__level_17__list__indent_3__list__indent_2_2__num">
                                    <inline name="unchecked" xml:id="_body__level_17__list__indent_3__list__indent_2_2__num__inline">&#x2610;</inline>
                                </num>
                                <content xml:id="_body__level_17__list__indent_3__list__indent_2_2__content">
                                    <p xml:id="_body__level_17__list__indent_3__list__indent_2_2__content__p">international organisations and their agencies (to be specified);</p>
                                </content>
                            </indent>
                            <indent leos:editable="false" xml:id="_body__level_17__list__indent_3__list__indent_3_3">
                                <num xml:id="_body__level_17__list__indent_3__list__indent_3_3__num">
                                    <inline name="unchecked" xml:id="_body__level_17__list__indent_3__list__indent_3_3__num__inline">&#x2610;</inline>
                                </num>
                                <content xml:id="_body__level_17__list__indent_3__list__indent_3_3__content">
                                    <p xml:id="_body__level_17__list__indent_3__list__indent_3_3__content__p">the EIB and the European Investment Fund;</p>
                                </content>
                            </indent>
                            <indent leos:editable="false" xml:id="_body__level_17__list__indent_3__list__indent_4_4">
                                <num xml:id="_body__level_17__list__indent_3__list__indent_4_4__num">
                                    <inline name="unchecked" xml:id="_body__level_17__list__indent_3__list__indent_4_4__num__inline">&#x2610;</inline>
                                </num>
                                <content xml:id="_body__level_17__list__indent_3__list__indent_4_4__content">
                                    <p xml:id="_body__level_17__list__indent_3__list__indent_4_4__content__p">bodies referred to in Articles 70 and 71 of the Financial Regulation;</p>
                                </content>
                            </indent>
                            <indent leos:editable="false" xml:id="_body__level_17__list__indent_3__list__indent_5_5">
                                <num xml:id="_body__level_17__list__indent_3__list__indent_5_5__num">
                                    <inline name="unchecked" xml:id="_body__level_17__list__indent_3__list__indent_5_5__num__inline">&#x2610;</inline>
                                </num>
                                <content xml:id="_body__level_17__list__indent_3__list__indent_5_5__content">
                                    <p xml:id="_body__level_17__list__indent_3__list__indent_5_5__content__p">public law bodies;</p>
                                </content>
                            </indent>
                            <indent leos:editable="false" xml:id="_body__level_17__list__indent_3__list__indent_6_6">
                                <num xml:id="_body__level_17__list__indent_3__list__indent_6_6__num">
                                    <inline name="unchecked" xml:id="_body__level_17__list__indent_3__list__indent_6_6__num__inline">&#x2610;</inline>
                                </num>
                                <content xml:id="_body__level_17__list__indent_3__list__indent_6_6__content">
                                    <p xml:id="_body__level_17__list__indent_3__list__indent_6_6__content__p">bodies governed by private law with a public service mission to the extent that they are provided with adequate financial guarantees;</p>
                                </content>
                            </indent>
                            <indent leos:editable="false" xml:id="_body__level_17__list__indent_3__list__indent_7_7">
                                <num xml:id="_body__level_17__list__indent_3__list__indent_7_7__num">
                                    <inline name="unchecked" xml:id="_body__level_17__list__indent_3__list__indent_7_7__num__inline">&#x2610;</inline>
                                </num>
                                <content xml:id="_body__level_17__list__indent_3__list__indent_7_7__content">
                                    <p xml:id="_body__level_17__list__indent_3__list__indent_7_7__content__p">bodies governed by the private law of a Member State that are entrusted with the implementation of a public-private partnership and that are provided with adequate financial guarantees;</p>
                                </content>
                            </indent>
                            <indent leos:editable="false" xml:id="_body__level_17__list__indent_3__list__indent_8">
                                <num xml:id="_body__level_17__list__indent_3__list__indent_8__num">
                                    <inline name="unchecked" xml:id="_body__level_17__list__indent_3__list__indent_8__num__inline">&#x2610;</inline>
                                </num>
                                <content xml:id="_body__level_17__list__indent_3__list__indent_8__content">
                                    <p xml:id="_body__level_17__list__indent_3__list__indent_8__content__p">bodies or persons entrusted with the implementation of specific actions in the CFSP pursuant to Title V of the TEU, and identified in the relevant basic act.</p>
                                </content>
                            </indent>
                        </list>
                    </indent>
                </list>
