                        <table style="border-collapse:collapse;width:50%;margin-left:0%;" xml:id="_body__level_31__subparagraph_5_5__content__table">
                            <tr xml:id="_body__level_31__subparagraph_5_5__content__table__tr_1">
                                <td rowspan="2" style="border:1px solid black;text-align:center;" xml:id="_body__level_31__subparagraph_5_5__content__table__tr_1__td_1">
                                    <p xml:id="_body__level_31__subparagraph_5_5__content__table__tr_1__td_1__p">Heading of multiannual financial framework</p>
                                </td>
                                <td style="border:1px solid black;text-align:center;" xml:id="_body__level_31__subparagraph_5_5__content__table__tr_1__td_2_2">
                                    <p xml:id="_body__level_31__subparagraph_5_5__content__table__tr_1__td_2_2__p">Budget line</p>
                                </td>
                                <td style="border:1px solid black;text-align:center;" xml:id="_body__level_31__subparagraph_5_5__content__table__tr_1__td_3_3">
                                    <p xml:id="_body__level_31__subparagraph_5_5__content__table__tr_1__td_3_3__p">Type of
                                        <br xml:id="_body__level_31__subparagraph_5_5__content__table__tr_1__td_3_3__p__br"/>
                                        expenditure
                                    </p>
                                </td>
                                <td colspan="4" style="border:1px solid black;text-align:center;" xml:id="_body__level_31__subparagraph_5_5__content__table__tr_1__td_4">
                                    <p xml:id="_body__level_31__subparagraph_5_5__content__table__tr_1__td_4__p">Contribution</p>
                                </td>
                            </tr>
                            <tr xml:id="_body__level_31__subparagraph_5_5__content__table__tr_2_2">
