            <level leos:depth="3" class="landscape" xml:id="_body__level_321" leos:deletable="false">
                <num xml:id="_body__level_321__num">3.2.1.</num>
                <heading leos:editable="false" xml:id="_body__level_321__heading">
                    <i xml:id="_body__level_321__heading__i">Summary of estimated impact on operational appropriations</i>
                </heading>
                <list leos:editable="false" class="CHECK" xml:id="_body__level_321__list">
                    <indent xml:id="_body__level_321__list__indent_1">
                        <num xml:id="_body__level_321__list__indent_1__num">
                            <inline name="unchecked" xml:id="_body__level_321__list__indent_1__num__inline">&#x2610;</inline>
                        </num>
                        <content xml:id="_body__level_321__list__indent_1__content">
                            <p xml:id="_body__level_321__list__indent_1__content__p">The proposal/initiative does not require the use of operational appropriations</p>
                        </content>
                    </indent>
                    <indent xml:id="_body__level_321__list__indent_2">
                        <num xml:id="_body__level_321__list__indent_2__num">
                            <inline name="unchecked" xml:id="_body__level_321__list__indent_2__num__inline">&#x2610;</inline>
                        </num>
                        <content xml:id="_body__level_321__list__indent_2__content">
                            <p xml:id="_body__level_321__list__indent_2__content__p">The proposal/initiative requires the use of operational appropriations, as explained below:</p>
                        </content>
                    </indent>
                </list>
                <subparagraph leos:editable="false" xml:id="_body__level_321__subparagraph_4_4a">
                    <content xml:id="_body__level_321__subparagraph_4_4a__content_a">
                        <p style="text-align: right;padding-right: 12%;" xml:id="_body__level_321__subparagraph_4_4a__content_content__p_2">EUR million (to three decimal places)</p>
                    </content>
                </subparagraph>
