                                            <p xml:id="_body__level_321__subparagraph_5_5__content__table_1__tr_1__td_4_4__p__authorialnote__p">Year N is the year in which implementation of the proposal/initiative starts. Please replace "N" by the expected first year of implementation (for instance: 2021). The same for the following years.</p>
