                <subparagraph  leos:editable="false" xml:id="_body__level_321__subparagraph_9_9">
                    <content xml:id="_body__level_321__subparagraph_9_9__content">
                        <p leos:editable="false" xml:id="_body__level_321__subparagraph_9_9__content__p_1">This section should be filled in using the ''budget data of an administrative nature'' to be firstly introduced in the
                            <a leos:editable="false" href="https://myintracomm.ec.europa.eu/corp/budget/financial-rules/legal-framework/internal-rules/Documents/2022-5-legislative-financial-statement-annex-en.docx" xml:id="_body__level_321__subparagraph_9_9__content__p_1__a">Annex to the Legislative Financial Statement</a>
                            (Annex 5 to the Commission decision on the internal rules for the implementation of the Commission section of the general budget of the European Union), which is uploaded to DECIDE for interservice consultation purposes.
                        </p>
                    </content>
                </subparagraph>
