                        <content xml:id="_body__level_323__list__indent_1__content">
                            <p xml:id="_body__level_323__list__indent_1__content__p">The proposal/initiative does not require the use of appropriations of an administrative nature</p>
                        </content>
                    </indent>
                    <indent xml:id="_body__level_323__list__indent_2">
                        <num xml:id="_body__level_323__list__indent_2__num">
                            <inline name="unchecked" xml:id="_body__level_323__list__indent_2__num__inline">&#x2610;</inline>
                        </num>
                        <content xml:id="_body__level_323__list__indent_2__content">
                            <p xml:id="_body__level_323__list__indent_2__content__p">The proposal/initiative requires the use of appropriations of an administrative nature, as explained below:</p>
                        </content>
                    </indent>
                </list>
                <subparagraph style="text-align: right;padding-right:20%;" xml:id="_body__level_323__subparagraph_4">
                    <content xml:id="_body__level_323__subparagraph_4__content">
                        <p xml:id="_body__level_323__subparagraph_4__content__p">EUR million (to three decimal places)</p>
                    </content>
                </subparagraph>
