                <subparagraph xml:id="_body__level_323__subparagraph_6">
                    <content xml:id="_body__level_323__subparagraph_6__content">
                        <p xml:id="_body__level_323__subparagraph_5__content__p">The appropriations required for human resources and other expenditure of an administrative nature will be met by appropriations from the DG that are already assigned to management of the action and/or have been redeployed within the DG, together if necessary with any additional allocation which may be granted to the managing DG under the annual allocation procedure and in the light of budgetary constraints.</p>
                    </content>
                </subparagraph>
            </level>
            <level leos:depth="4" class="landscape" xml:id="_body__level_3231" leos:deletable="false">
                <num xml:id="_body__level_3231__num">3.2.3.1</num>
                <heading leos:editable="false" xml:id="_body__level_3231__heading">
                    <i xml:id="_body__level_3231__heading__i">Estimated requirements of human resources</i>
                </heading>
                <list leos:editable="false" class="CHECK" xml:id="_body__level_3231__list">
                    <indent xml:id="_body__level_3231__list__indent_1">
                        <num xml:id="_body__level_3231__list__indent_1__num">
                            <inline name="unchecked" xml:id="_body__level_3231__list__indent_1__num__inline">&#x2610;</inline>
                        </num>
                        <content xml:id="_body__level_3231__list__indent_1__content">
                            <p xml:id="_body__level_3231__list__indent_1__content__p">The proposal/initiative does not require the use of human resources.</p>
                        </content>
                    </indent>
                    <indent xml:id="_body__level_3231__list__indent_2">
                        <num xml:id="_body__level_3231__list__indent_2__num">
                            <inline name="unchecked" xml:id="_body__level_3231__list__indent_2__num__inline">&#x2610;</inline>
                        </num>
                        <content xml:id="_body__level_3231__list__indent_2__content">
                            <p xml:id="_body__level_3231__list__indent_2__content__p">The proposal/initiative requires the use of human resources, as explained below:</p>
                        </content>
                    </indent>
                </list>
                <subparagraph leos:editable="false" xml:id="_body__level_3231__subparagraph_4" style="text-align: right;padding-right:10%;">
                    <content xml:id="_body__level_3231__subparagraph_4__content">
                        <p xml:id="_body__level_3231__subparagraph_4__content__p"><i>Estimate to be expressed in full time equivalent units</i></p>
                    </content>
                </subparagraph>
