                                <td style="border-top: none; border-left: none; border-bottom: solid windowtext 1.0pt; border-right: solid windowtext 1.0pt; " xml:id="_body__level_3231__subparagraph_5_5__content__table__tr_16__td_3_3">
                                    <p xml:id="_body__level_3231__subparagraph_5_5__content__table__tr_16__td_3_3__p">
                                        <b xml:id="_body__level_3231__subparagraph_5_5__content__table__tr_16__td_3_3__p__b"> </b>
                                    </p>
                                </td>
                                <td style="border-top: none; border-left: none; border-bottom: solid windowtext 1.0pt; border-right: solid windowtext 1.0pt; " xml:id="_body__level_3231__subparagraph_5_5__content__table__tr_16__td_4_4">
                                    <p xml:id="_body__level_3231__subparagraph_5_5__content__table__tr_16__td_4_4__p">
                                        <b xml:id="_body__level_3231__subparagraph_5_5__content__table__tr_16__td_4_4__p__b"> </b>
                                    </p>
                                </td>
                                <td style="border-top: none; border-left: none; border-bottom: solid windowtext 1.0pt; border-right: solid windowtext 1.0pt; " xml:id="_body__level_3231__subparagraph_5_5__content__table__tr_16__td_5_5">
                                    <p xml:id="_body__level_3231__subparagraph_5_5__content__table__tr_16__td_5_5__p">
                                        <b xml:id="_body__level_3231__subparagraph_5_5__content__table__tr_16__td_5_5__p__b"> </b>
                                    </p>
                                </td>
                                <td style="border-top: none; border-left: none; border-bottom: solid windowtext 1.0pt; border-right: solid windowtext 1.0pt; " xml:id="_body__level_3231__subparagraph_5_5__content__table__tr_16__td_6_6">
                                    <p xml:id="_body__level_3231__subparagraph_5_5__content__table__tr_16__td_6_6__p">
                                        <b xml:id="_body__level_3231__subparagraph_5_5__content__table__tr_16__td_6_6__p__b"> </b>
                                    </p>
                                </td>
                                <td style="border-top: none; border-left: none; border-bottom: solid windowtext 1.0pt; border-right: solid windowtext 1.0pt; " xml:id="_body__level_3231__subparagraph_5_5__content__table__tr_16__td_7">
                                    <p xml:id="_body__level_3231__subparagraph_5_5__content__table__tr_16__td_7__p">
                                        <b xml:id="_body__level_3231__subparagraph_5_5__content__table__tr_16__td_7__p__b"> </b>
                                    </p>
                                </td>
                                <td style="border-top: none; border-left: none; border-bottom: solid windowtext 1.0pt; border-right: solid windowtext 1.0pt; " xml:id="_body__level_3231__subparagraph_5_5__content__table__tr_16__td_8">
                                    <p xml:id="_body__level_3231__subparagraph_5_5__content__table__tr_16__td_8__p">
                                        <b xml:id="_body__level_3231__subparagraph_5_5__content__table__tr_16__td_8__p__b"> </b>
                                    </p>
                                </td>
                            </tr>
                        </table>
                    </content>
                </subparagraph>
                <subparagraph leos:allow-soft-enter="false" leos:deletable="false" leos:editable="true" xml:id="_body__level_3231__subparagraph_6_6">
                    <content xml:id="_body__level_3231__subparagraph_6_6__content">
                        <p xml:id="_body__level_3231__subparagraph_6_6__content__p_1">XX is the policy area or budget title concerned.</p>
                    </content>
                </subparagraph>
                <subparagraph leos:editable="false" xml:id="_body__level_3231__subparagraph_6_7">
                    <content xml:id="_body__level_3231__subparagraph_6_7__content">
                        <p xml:id="_body__level_3231__subparagraph_6_7__content__p_2">The human resources required will be met by staff from the DG who are already assigned to management of the action and/or have been redeployed within the DG, together if necessary with any additional allocation which may be granted to the managing DG under the annual allocation procedure and in the light of budgetary constraints.</p>
                    </content>
                </subparagraph>
                <subparagraph leos:editable="false" xml:id="_body__level_3231__subparagraph_7_7">
                    <content xml:id="_body__level_3231__subparagraph_7_7__content">
                        <p xml:id="_body__level_3231__subparagraph_7_7__content__p">Description of tasks to be carried out:</p>
                    </content>
                </subparagraph>
                <subparagraph leos:editable="true" leos:deletable="false" xml:id="_body__level_3231__subparagraph_8">
                    <content xml:id="_body__level_3231__subparagraph_8__content">
                        <table style="border-collapse:collapse; text-align:left;margin-bottom:25px;margin-left:0%;" xml:id="_body__level_3231__subparagraph_8__content__table">
                            <tr xml:id="_body__level_3231__subparagraph_8__content__table__tr_1">
                                <td style="border:1px solid black;" xml:id="_body__level_3231__subparagraph_8__content__table__tr_1__td_1">
                                    <p xml:id="_body__level_3231__subparagraph_8__content__table__tr_1__td_1__p">Officials and temporary staff</p>
                                </td>
                                <td style="border:1px solid black;width:500px" xml:id="_body__level_3231__subparagraph_8__content__table__tr_1__td_2">
                                    <p xml:id="_body__level_3231__subparagraph_8__content__table__tr_1__td_2__p"/>
                                </td>
                            </tr>
                            <tr xml:id="_body__level_3231__subparagraph_8__content__table__tr_2">
                                <td style="border:1px solid black;" xml:id="_body__level_3231__subparagraph_8__content__table__tr_2__td_1">
                                    <p xml:id="_body__level_3231__subparagraph_8__content__table__tr_2__td_1__p">External staff</p>
                                </td>
                                <td style="border:1px solid black;width:500px" xml:id="_body__level_3231__subparagraph_8__content__table__tr_2__td_2">
                                    <p xml:id="_body__level_3231__subparagraph_8__content__table__tr_2__td_2__p"/>
                                </td>
                            </tr>
                        </table>
                    </content>
                </subparagraph>
            </level>
            <level leos:editable="true" leos:depth="3" xml:id="_body__level_324" leos:deletable="false">
                <num xml:id="_body__level_324__num">3.2.4.</num>
                <heading leos:editable="false" xml:id="_body__level_324__heading">
                    <i leos:editable="false" xml:id="_body__level_324__heading__i">Compatibility with the current multiannual financial framework</i>
                </heading>
                <subparagraph leos:editable="false" xml:id="_body__level_324__subparagraph">
                    <content xml:id="_body__level_324__subparagraph__content">
                        <p leos:editable="false" xml:id="_body__level_324__subparagraph__content__p">The proposal/initiative :</p>
                    </content>
                </subparagraph>
                <list leos:editable="true" class="CHECK" xml:id="_body__level_324__list">
                    <indent xml:id="_body__level_324__list__indent_1">
                        <num xml:id="_body__level_324__list__indent_1__num">
                            <inline name="unchecked" xml:id="_body__level_324__list__indent_1__num__inline">&#x2610;</inline>
                        </num>
                        <subparagraph leos:editable="false" xml:id="_body__level_324__list__indent_1__subparagraph_2">
                            <content xml:id="_body__level_324__list__indent_1__subparagraph_2__content">
                                <p leos:editable="false" xml:id="_body__level_324__list__indent_1__subparagraph_2__content__p">can be fully financed through redeployment within the relevant heading of the Multiannual Financial Framework (MFF).</p>
                            </content>
                        </subparagraph>
                        <subparagraph leos:editable="true" xml:id="_body__level_324__list__indent_1__subparagraph_3">
                            <content xml:id="_body__level_324__list__indent_1__subparagraph_3__content">
                                <p xml:id="_body__level_324__list__indent_1__subparagraph_3__content__p">Explain what reprogramming is required, specifying the budget lines concerned and the corresponding amounts. Please provide an excel table in the case of major reprogramming.</p>
                            </content>
                        </subparagraph>
                    </indent>
                    <indent xml:id="_body__level_324__list__indent_2_2">
                        <num xml:id="_body__level_324__list__indent_2_2__num">
                            <inline name="unchecked" xml:id="_body__level_324__list__indent_2_2__num__inline">&#x2610;</inline>
                        </num>
                        <subparagraph leos:editable="false" xml:id="_body__level_324__list__indent_2_2__subparagraph_2">
                            <content xml:id="_body__level_324__list__indent_2_2__subparagraph_2__content">
                                <p leos:editable="false" xml:id="_body__level_324__list__indent_2_2__subparagraph_2__content__p">requires use of the unallocated margin under the relevant heading of the MFF and/or use of the special instruments as defined in the MFF Regulation.</p>
                            </content>
                        </subparagraph>
                        <subparagraph leos:editable="true" xml:id="_body__level_324__list__indent_2_2__subparagraph_3">
                            <content xml:id="_body__level_324__list__indent_2_2__subparagraph_3__content">
                                <p xml:id="_body__level_324__list__indent_2_2__subparagraph_3__content__p">Explain what is required, specifying the headings and budget lines concerned, the corresponding amounts, and the instruments proposed to be used.</p>
                            </content>
                        </subparagraph>
                    </indent>
                    <indent xml:id="_body__level_324__list__indent_3">
                        <num xml:id="_body__level_324__list__indent_3__num">
                            <inline name="unchecked" xml:id="_body__level_324__list__indent_3__num__inline">&#x2610;</inline>
                        </num>
                        <subparagraph leos:editable="false" xml:id="_body__level_324__list__indent_3__subparagraph_2">
                            <content xml:id="_body__level_324__list__indent_3__subparagraph_2__content">
                                <p leos:editable="false" xml:id="_body__level_324__list__indent_3__subparagraph_2__content__p">requires a revision of the MFF.</p>
                            </content>
                        </subparagraph>
                        <subparagraph leos:editable="true" xml:id="_body__level_324__list__indent_3__subparagraph_3">
                            <content xml:id="_body__level_324__list__indent_3__subparagraph_3__content">
                                <p xml:id="_body__level_324__list__indent_3__subparagraph_3__content__p">Explain what is required, specifying the headings and budget lines concerned and the corresponding amounts.</p>
                            </content>
                        </subparagraph>
                    </indent>
                </list>
            </level>
            <level leos:depth="3" class="landscape" xml:id="_body__level_325" leos:deletable="false">
                <num xml:id="_body__level_325__num">3.2.5.</num>
                <heading leos:editable="false" xml:id="_body__level_325__heading">
                    <i xml:id="_body__level_325__heading__i">Third-party contributions</i>
                </heading>
                <subparagraph leos:editable="false" xml:id="_body__level_325__subparagraph">
                    <content xml:id="_body__level_325__subparagraph__content">
                        <p leos:editable="false" xml:id="_body__level_325__subparagraph__content__p">The proposal/initiative:</p>
                    </content>
                </subparagraph>
                <list leos:editable="false" class="CHECK" xml:id="_body__level_325__list">
                    <indent xml:id="_body__level_325__list__indent_1">
                        <num xml:id="_body__level_325__list__indent_1__num">
                            <inline name="unchecked" xml:id="_body__level_325__list__indent_1__num__inline">&#x2610;</inline>
                        </num>
                        <subparagraph leos:editable="false" xml:id="_body__level_325__list__indent_1__subparagraph">
                            <content xml:id="_body__level_325__list__indent_1__subparagraph__content">
                                <p xml:id="_body__level_325__list__indent_1__subparagraph__content__p">does not provide for co-financing by third parties</p>
                            </content>
                        </subparagraph>
                    </indent>
                    <indent xml:id="_body__level_325__list__indent_2">
                        <num xml:id="_body__level_325__list__indent_2__num">
                            <inline name="unchecked" xml:id="_body__level_325__list__indent_2__num__inline">&#x2610;</inline>
                        </num>
                        <subparagraph leos:editable="false" xml:id="_body__level_325__list__indent_2__subparagraph">
                            <content xml:id="_body__level_325__list__indent_2__subparagraph__content">
                                <p xml:id="_body__level_325__list__indent_2__subparagraph__content__p">provides for the co-financing by third parties estimated below:</p>
                            </content>
                        </subparagraph>
                    </indent>
                </list>
                <subparagraph leos:editable="false" style="text-align: right;padding-right:4%;" xml:id="_body__level_325__subparagraph_4">
                    <content xml:id="_body__level_325__subparagraph_4__content">
                        <p xml:id="_body__level_325__subparagraph_4__content__p">Appropriations in EUR million (to three decimal places)</p>
                    </content>
                </subparagraph>
                <subparagraph leos:editable="true" leos:deletable="false" xml:id="_body__level_325__subparagraph_5">
                    <content xml:id="_body__level_325__subparagraph_5__content">
                        <table style="border-collapse:collapse;text-align:left;margin-bottom:25px;margin-left:0%;" xml:id="_body__level_325__subparagraph_5__content__table">
                            <tr xml:id="_body__level_325__subparagraph_5__content__table__tr_1">
                                <td style="border:1px solid black;" xml:id="_body__level_325__subparagraph_5__content__table__tr_1__td_1">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_1__td_1__p"/>
                                </td>
                                <td style="border:1px solid black;text-align:center;" xml:id="_body__level_325__subparagraph_5__content__table__tr_1__td_2_2">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_1__td_2_2__p">Year
                                        <b xml:id="_body__level_325__subparagraph_5__content__table__tr_1__td_2_2__p__b">N
                                            <authorialNote marker="16" placement="bottom" xml:id="_body__level_325__subparagraph_5__content__table__tr_1__td_2_2__p__b__authorialnote">
                                                <p xml:id="_body__level_325__subparagraph_5__content__table__tr_1__td_2_2__p__b__authorialnote__p">Year N is the year in which implementation of the proposal/initiative starts. Please replace "N" by the expected first year of implementation (for instance: 2021). The same for the following years.</p>
                                            </authorialNote>
                                        </b>
                                    </p>
                                </td>
                                <td style="border:1px solid black;text-align:center;" xml:id="_body__level_325__subparagraph_5__content__table__tr_1__td_3_3">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_1__td_3_3__p">Year
                                        <b xml:id="_body__level_325__subparagraph_5__content__table__tr_1__td_3_3__p__b">N+1</b>
                                    </p>
                                </td>
                                <td style="border:1px solid black;text-align:center;" xml:id="_body__level_325__subparagraph_5__content__table__tr_1__td_4_4">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_1__td_4_4__p">Year
                                        <b xml:id="_body__level_325__subparagraph_5__content__table__tr_1__td_4_4__p__b">N+2</b>
                                    </p>
                                </td>
                                <td style="border:1px solid black;text-align:center;" xml:id="_body__level_325__subparagraph_5__content__table__tr_1__td_5_5">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_1__td_5_5__p">Year
                                        <b xml:id="_body__level_325__subparagraph_5__content__table__tr_1__td_5_5__p__b">N+3</b>
                                    </p>
                                </td>
                                <td colspan="2" style="border:1px solid black;text-align:center;" xml:id="_body__level_325__subparagraph_5__content__table__tr_1__td_6_6">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_1__td_6_6__p">Enter as many years as necessary to show the duration of the impact (see point 1.6)</p>
                                </td>
                                <td style="border:1px solid black;text-align:center;" xml:id="_body__level_325__subparagraph_5__content__table__tr_1__td_7">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_1__td_7__p">Total</p>
                                </td>
                            </tr>
                            <tr xml:id="_body__level_325__subparagraph_5__content__table__tr_2_2">
                                <td style="border:1px solid black;" xml:id="_body__level_325__subparagraph_5__content__table__tr_2_2__td_1">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_2_2__td_1__p">Specify the co-financing body</p>
                                </td>
                                <td style="border:1px solid black;" xml:id="_body__level_325__subparagraph_5__content__table__tr_2_2__td_2_2">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_2_2__td_2_2__p"/>
                                </td>
                                <td style="border:1px solid black;" xml:id="_body__level_325__subparagraph_5__content__table__tr_2_2__td_3_3">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_2_2__td_3_3__p"/>
                                </td>
                                <td style="border:1px solid black;text-align:right;" xml:id="_body__level_325__subparagraph_5__content__table__tr_2_2__td_4_4">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_2_2__td_4_4__p"/>
                                </td>
                                <td style="border:1px solid black;text-align:right;" xml:id="_body__level_325__subparagraph_5__content__table__tr_2_2__td_5_5">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_2_2__td_5_5__p"/>
                                </td>
                                <td style="border:1px solid black;text-align:right;" xml:id="_body__level_325__subparagraph_5__content__table__tr_2_2__td_6_6">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_2_2__td_6_6__p"/>
                                </td>
                                <td style="border:1px solid black;text-align:right;" xml:id="_body__level_325__subparagraph_5__content__table__tr_2_2__td_7_7">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_2_2__td_7_7__p"/>
                                </td>
                                <td style="border:1px solid black;text-align:right;" xml:id="_body__level_325__subparagraph_5__content__table__tr_2_2__td_8">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_2_2__td_8__p"/>
                                </td>
                            </tr>
                            <tr xml:id="_body__level_325__subparagraph_5__content__table__tr_3">
                                <td style="border:1px solid black;" xml:id="_body__level_325__subparagraph_5__content__table__tr_3__td_1">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_3__td_1__p">TOTAL appropriations co-financed</p>
                                </td>
                                <td style="border:1px solid black;" xml:id="_body__level_325__subparagraph_5__content__table__tr_3__td_2_2">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_3__td_2_2__p"/>
                                </td>
                                <td style="border:1px solid black;" xml:id="_body__level_325__subparagraph_5__content__table__tr_3__td_3_3">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_3__td_3_3__p"/>
                                </td>
                                <td style="border:1px solid black;text-align:right;" xml:id="_body__level_325__subparagraph_5__content__table__tr_3__td_4_4">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_3__td_4_4__p"/>
                                </td>
                                <td style="border:1px solid black;text-align:right;" xml:id="_body__level_325__subparagraph_5__content__table__tr_3__td_5_5">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_3__td_5_5__p"/>
                                </td>
                                <td style="border:1px solid black;text-align:right;" xml:id="_body__level_325__subparagraph_5__content__table__tr_3__td_6_6">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_3__td_6_6__p"/>
                                </td>
                                <td style="border:1px solid black;text-align:right;" xml:id="_body__level_325__subparagraph_5__content__table__tr_3__td_7_7">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_3__td_7_7__p"/>
                                </td>
                                <td style="border:1px solid black;text-align:right;" xml:id="_body__level_325__subparagraph_5__content__table__tr_3__td_8">
                                    <p xml:id="_body__level_325__subparagraph_5__content__table__tr_3__td_8__p"/>
                                </td>
                            </tr>
                        </table>
                    </content>
