            </level>
            <level leos:depth="2" class="landscape" xml:id="_body__level_33" leos:deletable="false">
                <num leos:editable="false" xml:id="_body__level_33__num">3.3.</num>
                <heading leos:editable="false" xml:id="_body__level_33__heading">
                    <b leos:editable="false" xml:id="_body__level_33__heading__b">Estimated impact on revenue</b>
                </heading>
                <list leos:editable="false" class="CHECK" xml:id="_body__level_33__list">
                    <indent leos:editable="false" xml:id="_body__level_33__list__indent_1">
                        <num xml:id="_body__level_33__list__indent_1__num">
                            <inline name="unchecked" xml:id="_body__level_33__list__indent_1__num__inline">&#x2610;</inline>
                        </num>
                        <content xml:id="_body__level_33__list__indent_1__content">
                            <p leos:editable="false" xml:id="_body__level_33__list__indent_1__content__p">The proposal/initiative has no financial impact on revenue.</p>
                        </content>
                    </indent>
                    <indent leos:editable="false" xml:id="_body__level_33__list__indent_2">
                        <num xml:id="_body__level_33__list__indent_2__num">
                            <inline name="unchecked" xml:id="_body__level_33__list__indent_2__num__inline">&#x2610;</inline>
                        </num>
                        <subparagraph leos:editable="false" xml:id="_body__level_33__list__indent_2__subparagraph">
                            <content xml:id="_body__level_33__list__indent_2__subparagraph__content">
                                <p leos:editable="false" xml:id="_body__level_33__list__indent_2__subparagraph__content__p">The proposal/initiative has the following financial impact:</p>
                            </content>
                        </subparagraph>
                        <list leos:editable="false" class="CHECK" xml:id="_body__level_33__list__indent_2__list">
                            <indent leos:editable="false" xml:id="_body__level_33__list__indent_2__list__indent_1">
                                <num xml:id="_body__level_33__list__indent_2__list__indent_1__num">
                                    <inline name="unchecked" xml:id="_body__level_33__list__indent_2__list__indent_1__num__inline">&#x2610;</inline>
                                </num>
                                <content xml:id="_body__level_33__list__indent_2__list__indent_1__content">
                                    <p leos:editable="false" xml:id="_body__level_33__list__indent_2__list__indent_1__content__p">on own resources</p>
                                </content>
                            </indent>
                            <indent leos:editable="false" xml:id="_body__level_33__list__indent_2__list__indent_2_2">
                                <num xml:id="_body__level_33__list__indent_2__list__indent_2_2__num">
                                    <inline name="unchecked" xml:id="_body__level_33__list__indent_2__list__indent_2_2__num__inline">&#x2610;</inline>
                                </num>
                                <list leos:editable="false" class="CHECK" xml:id="_body__level_33__list__indent_2__list__indent_2_2_list">
                                    <subparagraph leos:editable="false" xml:id="_body__level_33__list__indent_2__list__indent_2_2_list_subparagraph">
                                        <content xml:id="_body__level_33__list__indent_2__list__indent_2_2_list_subparagraph_content">
                                            <p leos:editable="false" xml:id="_body__level_33__list__indent_2__list__indent_2_2_list_subparagraph_content_p">on other revenue</p>
                                        </content>
                                    </subparagraph>
                                    <indent leos:editable="false" xml:id="_body__level_33__list__indent_2__list__indent_3">
                                        <num xml:id="_body__level_33__list__indent_2__list__indent_3__num" ><inline name="unchecked" xml:id="_body__level_33__list__indent_2__list__indent_3__content_inline">&#x2610;</inline></num>
                                        <content xml:id="_body__level_33__list__indent_2__list__indent_3__content">
                                            <p leos:editable="false" xml:id="_body__level_33__list__indent_2__list__indent_3__content__p">please indicate, if the revenue is assigned to expenditure lines  </p>
                                        </content>
                                    </indent>
                                </list>
                            </indent>
                        </list>
                    </indent>
                </list>
                <subparagraph leos:editable="false" xml:id="_body__level_33__subparagraph_4" style="text-align: right;padding-right:20%;">
                    <content xml:id="_body__level_33__subparagraph_4__content">
                        <p xml:id="_body__level_33__subparagraph_4__content__p">EUR million (to three decimal places)</p>
                    </content>
                </subparagraph>
                <subparagraph leos:editable="true" leos:deletable="false" xml:id="_body__level_33__subparagraph_5_5">
                    <content xml:id="_body__level_33__subparagraph_5_5__content">
                        <table style="border-collapse:collapse; text-align:center;vertical-align:middle;margin-left:0%;" xml:id="_body__level_33__subparagraph_5_5__content__table">
                            <tr xml:id="_body__level_33__subparagraph_5_5__content__table__tr_1">
                                <td rowspan="2" style="border:1px solid black;" xml:id="_body__level_33__subparagraph_5_5__content__table__tr_1__td_1">
                                    <p xml:id="_body__level_33__subparagraph_5_5__content__table__tr_1__td_1__p">Budget revenue line:</p>
                                </td>
                                <td rowspan="2" style="border:1px solid black;" xml:id="_body__level_33__subparagraph_5_5__content__table__tr_1__td_2_2">
                                    <p xml:id="_body__level_33__subparagraph_5_5__content__table__tr_1__td_2_2__p">Appropriations available for the current financial year</p>
                                </td>
                                <td colspan="7" style="border:1px solid black;" xml:id="_body__level_33__subparagraph_5_5__content__table__tr_1__td_3">
                                    <p xml:id="_body__level_33__subparagraph_5_5__content__table__tr_1__td_3__p">Impact of the proposal/initiative
                                        <authorialNote marker="17" placement="bottom" xml:id="_body__level_33__subparagraph_5_5__content__table__tr_1__td_3__p__authorialnote">
                                            <p xml:id="_body__level_33__subparagraph_5_5__content__table__tr_1__td_3__p__authorialnote__p">   As regards traditional own resources (customs duties, sugar levies), the amounts indicated must be net amounts, i.e. gross amounts after deduction of 20 % for collection costs.</p>
                                        </authorialNote>
                                    </p>
                                </td>
                            </tr>
                            <tr xml:id="_body__level_33__subparagraph_5_5__content__table__tr_2_2">
                                <td style="border:1px solid black;" xml:id="_body__level_33__subparagraph_5_5__content__table__tr_2_2__td_1">
                                    <p xml:id="_body__level_33__subparagraph_5_5__content__table__tr_2_2__td_1__p">Year
                                        <br xml:id="_body__level_33__subparagraph_5_5__content__table__tr_2_2__td_1__p__br"/>
                                        N
                                    </p>
                                </td>
                                <td style="border:1px solid black;" xml:id="_body__level_33__subparagraph_5_5__content__table__tr_2_2__td_2_2">
                                    <p xml:id="_body__level_33__subparagraph_5_5__content__table__tr_2_2__td_2_2__p">Year
                                        <br xml:id="_body__level_33__subparagraph_5_5__content__table__tr_2_2__td_2_2__p__br"/>
                                        N+1
                                    </p>
                                </td>
                                <td style="border:1px solid black;" xml:id="_body__level_33__subparagraph_5_5__content__table__tr_2_2__td_3_3">
                                    <p xml:id="_body__level_33__subparagraph_5_5__content__table__tr_2_2__td_3_3__p">Year
                                        <br xml:id="_body__level_33__subparagraph_5_5__content__table__tr_2_2__td_3_3__p__br"/>
                                        N+2
                                    </p>
                                </td>
                                <td style="border:1px solid black;" xml:id="_body__level_33__subparagraph_5_5__content__table__tr_2_2__td_4_4">
                                    <p xml:id="_body__level_33__subparagraph_5_5__content__table__tr_2_2__td_4_4__p">Year
                                        <br xml:id="_body__level_33__subparagraph_5_5__content__table__tr_2_2__td_4_4__p__br"/>
                                        N+3
                                    </p>
                                </td>
                                <td colspan="3" style="border:1px solid black;" xml:id="_body__level_33__subparagraph_5_5__content__table__tr_2_2__td_5">
                                    <p xml:id="_body__level_33__subparagraph_5_5__content__table__tr_2_2__td_5__p">Enter as many years as necessary to show the duration of the impact (see point 1.6)</p>
                                </td>
                            </tr>
                            <tr xml:id="_body__level_33__subparagraph_5_5__content__table__tr_3">
                                <td style="border:1px solid black;" xml:id="_body__level_33__subparagraph_5_5__content__table__tr_3__td_1">
                                    <p xml:id="_body__level_33__subparagraph_5_5__content__table__tr_3__td_1__p">Article ………….</p>
                                </td>
                                <td style="border:1px solid black;" xml:id="_body__level_33__subparagraph_5_5__content__table__tr_3__td_2_2">
                                    <p xml:id="_body__level_33__subparagraph_5_5__content__table__tr_3__td_2_2__p"/>
                                </td>
                                <td style="border:1px solid black;" xml:id="_body__level_33__subparagraph_5_5__content__table__tr_3__td_3_3">
                                    <p xml:id="_body__level_33__subparagraph_5_5__content__table__tr_3__td_3_3__p"/>
                                </td>
                                <td style="border:1px solid black;" xml:id="_body__level_33__subparagraph_5_5__content__table__tr_3__td_4_4">
                                    <p xml:id="_body__level_33__subparagraph_5_5__content__table__tr_3__td_4_4__p"/>
                                </td>
                                <td style="border:1px solid black;" xml:id="_body__level_33__subparagraph_5_5__content__table__tr_3__td_5_5">
                                    <p xml:id="_body__level_33__subparagraph_5_5__content__table__tr_3__td_5_5__p"/>
                                </td>
                                <td style="border:1px solid black;" xml:id="_body__level_33__subparagraph_5_5__content__table__tr_3__td_6_6">
                                    <p xml:id="_body__level_33__subparagraph_5_5__content__table__tr_3__td_6_6__p"/>
                                </td>
                                <td style="border:1px solid black;" xml:id="_body__level_33__subparagraph_5_5__content__table__tr_3__td_7_7">
                                    <p xml:id="_body__level_33__subparagraph_5_5__content__table__tr_3__td_7_7__p"/>
                                </td>
                                <td style="border:1px solid black;" xml:id="_body__level_33__subparagraph_5_5__content__table__tr_3__td_8_8">
                                    <p xml:id="_body__level_33__subparagraph_5_5__content__table__tr_3__td_8_8__p"/>
                                </td>
                                <td style="border:1px solid black;" xml:id="_body__level_33__subparagraph_5_5__content__table__tr_3__td_9">
                                    <p xml:id="_body__level_33__subparagraph_5_5__content__table__tr_3__td_9__p"/>
                                </td>
                            </tr>
                        </table>
                    </content>
                </subparagraph>
                <subparagraph leos:editable="false" xml:id="_body__level_33__subparagraph_6_6">
                    <content xml:id="_body__level_33__subparagraph_6_6__content">
                        <p xml:id="_body__level_33__subparagraph_6_6__content__p">For assigned revenue, specify the budget expenditure line(s) affected.</p>
                    </content>
                </subparagraph>
                <subparagraph leos:editable="true" leos:deletable="false" xml:id="_body__level_33__subparagraph_7_7">
                    <content xml:id="_body__level_33__subparagraph_7_7__content">
                        <p xml:id="_body__level_33__subparagraph_7_7__content__p">[...]</p>
                    </content>
                </subparagraph>
                <subparagraph leos:editable="false" xml:id="_body__level_33__subparagraph_8_8">
                    <content xml:id="_body__level_33__subparagraph_8_8__content">
                        <p xml:id="_body__level_33__subparagraph_8_8__content__p">Other remarks (e.g. method/formula used for calculating the impact on revenue or any other information).</p>
                    </content>
                </subparagraph>
                <subparagraph leos:editable="true" leos:deletable="false" xml:id="_body__level_33__subparagraph_9">
                    <content xml:id="_body__level_33__subparagraph_9__content">
                        <p xml:id="_body__level_33__subparagraph_9__content__p">[...]</p>
                    </content>
                </subparagraph>
            </level>
        </mainBody>
    </doc>
</akomaNtoso><!--/legislative_financial_statement-->';
