                <citation xml:id="_cit_4" leos:editable="true">
                    <p xml:id="_cit_4__p">Having regard to the opinion of the European Parliament<authorialNote xml:id="_authorialnote_1" marker="1" placement="bottom"><p xml:id="_authorialNote_1__p">OJ C [...], [...], p. [...]</p></authorialNote>,</p>
                </citation>
                <citation xml:id="_cit_5" leos:editable="true">
                    <p xml:id="_cit_5__p">Having regard to the opinion of the European Economic and Social Committee<authorialNote xml:id="_authorialnote_2" marker="2" placement="bottom"><p xml:id="_authorialNote_2__p">OJ C [...], [...], p. [...]</p></authorialNote>,</p>
                </citation>
                <citation xml:id="_cit_6" leos:editable="true">
                    <p xml:id="_cit_6__p">Having regard to the opinion of the Committee of the Regions<authorialNote xml:id="_authorialnote_3" marker="3" placement="bottom"><p xml:id="_authorialNote_3__p">OJ C [...], [...], p. [...]</p></authorialNote>,</p>
                </citation>
                <citation xml:id="_cit_7" leos:editable="true">
                    <p xml:id="_cit_7__p">Acting in accordance with the ordinary legislative procedure,</p>
                </citation>
            </citations>
            <recitals xml:id="_recs" leos:editable="false">
                <intro xml:id="_recitalsIntro"><p xml:id="_recs_intro">Whereas:</p></intro>
                <recital xml:id="_rec_1" leos:editable="true">
