                <heading xml:id="_art_3__heading">Entry into force</heading>
                <paragraph xml:id="_art_3__para_1">
                    <content xml:id="_art_3__para_1__content">
                        <p xml:id="_art_3__para_1__content__p">This Decision shall enter into force on the [...] day following that of its publication in the <i xml:id="_art_3__para_1__content__p__i">Official Journal of the European Union</i>.</p>
                    </content>
